    "bellingham-tech-adn": {"prerequisites":[{"course":"Intro to Statistics","code":"MATH& 146","category":"stats","min_grade":"B","within_years":"none","by_when":"apply","one_of":null},{"course":"Human A & P 1","code":"BIOL& 241","category":"ap1","min_grade":"B","within_years":"none","by_when":"apply","one_of":null},{"course":"Human A & P 2","code":"BIOL& 242","category":"ap2","min_grade":"B","within_years":"none","by_when":"apply","one_of":null},{"course":"Microbiology","code":"BIOL& 260","category":"micro","min_grade":"B","within_years":"none","by_when":"apply","one_of":null},{"course":"Introduction to Chemistry","code":"CHEM& 121 or CHEM& 161","category":"chem","min_grade":"B","within_years":"none","by_when":"apply","one_of":null},{"course":"English Composition I","code":"ENGL& 101","category":"eng1","min_grade":"B","within_years":"none","by_when":"apply","one_of":null},{"course":"Lifespan Psychology","code":"PSYC& 200","category":"lifespan","min_grade":"B","within_years":"none","by_when":"apply","one_of":null},{"course":"General Psychology","code":"PSYC& 100","category":"psych","min_grade":"C","within_years":"none","by_when":"apply","one_of":null},{"course":"General Biology with lab","code":"BIOL& 160","category":"bio","min_grade":"C","within_years":"none","by_when":"apply","one_of":null},{"course":"Communication electives, 5 credits (CMST& 210 no longer accepted)","code":null,"category":"speech","min_grade":"C","within_years":"none","by_when":"apply","one_of":null},{"course":"Humanities electives, 10 credits (only 5 credits of foreign language)","code":null,"category":"humanities","min_grade":"C","within_years":"none","by_when":"apply","one_of":null}],"rules":{"gpa_overall_min":"not_published","gpa_prereq_min":"not_published","gpa_science_min":"not_published","exam":"none","selection":"points","points":{"max":"not_published","sheet_url":"https://www.btc.edu/Academics/DegreesAndCertificates/Nursing/Nursing-DTA-MRP-AssociateDegree.html","earns_points":["15 or more credits of nursing prerequisites completed at BTC","30 or more credits of nursing prerequisites completed at BTC","Nursing or Allied Health degree or certificate completed at BTC","Applied last academic year with a complete application","Applied the last 2 consecutive years with a complete application"],"ties":"not_published"},"retakes":{"counts":"see_text","max_attempts":"not_published","window_years":"not_published"},"local_priority":"not_published","seats":{"per_year":60,"applicants":"not_published","year":"2027-28","source_url":"https://www.btc.edu/Academics/DegreesAndCertificates/Nursing/Nursing-DTA-MRP-AssociateDegree.html"}},"wording":{"prerequisites":"All courses at least 5 quarter / 3 semester credits. Minimum B (3.0): MATH& 146, BIOL& 241, BIOL& 242, BIOL& 260, CHEM& 121 or 161, ENGL& 101, PSYC& 200. Minimum C (2.0): PSYC& 100, BIOL& 160, 5 credits Communication, 10 credits Humanities. Must be Program-Ready to apply. FAQ: general education courses \"are accepted no matter when they are completed.\"","gpa":"FAQ: \"BTC does not rank applicants by their overall GPA or whether they have a previous degree.\" No GPA minimum stated beyond course grades.","exam":"No entrance exam listed; English and math placement through Guided Self-Placement.","selection":"60 students enter in three cohorts each academic year through the Annual Program Ready List-Nursing (APL-N); applicants are ranked by points.","points":"One point each: 15+ credits of nursing prerequisites at BTC; 30+ credits at BTC; BTC Nursing or Allied Health degree/certificate; applied last academic year; applied last 2 consecutive years. Program/certificate credits earn no points.","retakes":"\"Repeated courses count only once\" (for points).","local_priority":null,"seats":"\"60 students\" enter in three cohorts each academic year."},"source_urls":["https://www.btc.edu/Academics/DegreesAndCertificates/Nursing/Nursing-DTA-MRP-AssociateDegree.html","https://www.btc.edu/files/Documents/Publications/Programs/2-Year%20Nursing%20Admissions%20Process%20FAQ%2025-26_10-9-25.pdf"],"last_verified":"2026-11-26","academic_year":"2027-28 application cycle","deadline":"2027-28: portal opens Jan 15, 2027 9:00 AM (closed Mar 19 - Apr 1, 2027 for grade processing); priority deadline Apr 15, 2027 (decisions mid-May); second priority deadline Jul 6, 2027 (decisions mid-August).","notes":"Must be Program-Ready: all prerequisites done, outside transcripts submitted/evaluated 6-8 weeks before the deadline, and an approved Healthcare Experience Verification form before applying (FAQ: healthcare training completed within the last five years; approval good five years). The program page also says the portal reopens April 1, 2027 (after the temporary grade-processing closure). The Oct 2025 FAQ says the window is open January to July 31. Waitlist position is not disclosed; list is wiped each year."},
