    "heritage-bsn": {"prerequisites":[{"course":"Introduction to General Chemistry with lab (4 sem/5 qtr credits; Heritage: CHEM 101/101L or CHEM 110/110L)","code":"CHEM 101/101L or CHEM 110/110L","category":"chem","min_grade":"C","within_years":"not_published","by_when":"see_text","one_of":null},{"course":"Organic and Biochemistry with lab (4 sem/5 qtr credits)","code":null,"category":"chem_ob","min_grade":"C+","within_years":"not_published","by_when":"see_text","one_of":null},{"course":"Introduction to Biology with lab (4 sem/5 qtr credits)","code":null,"category":"bio","min_grade":"C+","within_years":"not_published","by_when":"see_text","one_of":null},{"course":"College English (3 sem/5 qtr credits)","code":null,"category":"eng1","min_grade":"C+","within_years":"not_published","by_when":"see_text","one_of":null},{"course":"College Psychology (3 sem/5 qtr credits)","code":null,"category":"psych","min_grade":"C+","within_years":"not_published","by_when":"see_text","one_of":"g1"},{"course":"College Sociology (3 sem/5 qtr credits)","code":null,"category":"soc","min_grade":"C+","within_years":"not_published","by_when":"see_text","one_of":"g1"},{"course":"Anatomy with lab (listed for the Heritage pre-nursing pathway)","code":"BIOL 340/340L","category":"anatomy","min_grade":"C","within_years":"not_published","by_when":"see_text","one_of":null}],"rules":{"gpa_overall_min":3,"gpa_prereq_min":"not_published","gpa_science_min":2.75,"exam":{"name":"HESI A2","min_overall":"not_published","min_sections":"75% in each academic category","max_attempts":2,"valid_months":24},"selection":"competitive","points":"not_applicable","retakes":"not_published","local_priority":"not_published","seats":"not_published"},"wording":{"prerequisites":"Transfer: \"Each of the following college level courses must be completed with C+ or better... with the exception of a [C] or better in BIO 340/L and CHEM 101/L\": 4 semester or 5 quarter credits of Introduction to General Chemistry with lab; Organic and Biochemistry with lab; Introduction to Biology with lab; 3 semester or 5 quarter credits of college English; college Psychology or Sociology. Pre-nursing: \"C+ or better in all required prerequisite courses prior to admission\".","gpa":"\"Overall College GPA must be 3.0 or higher, with overall science GPA of 2.75 or better.\"","exam":"\"To be considered for selection, the applicant must achieve a minimum of 75% in each of the academic categories.\" \"Students have the option to retake the test one time within the same application cycle.\" \"Test results must be less than two years old at the time of application.\"","selection":"Admission is competitive; completing prerequisites does not guarantee admission. Four NursingCAS essays (250 words each) scored by a rubric; interview may be required.","points":null,"retakes":null,"local_priority":null,"seats":null},"source_urls":["https://heritage.edu/admissions/nursing-admissions/hesi-admission-assessment/","https://heritage.edu/admissions/nursing-admissions/"],"last_verified":"2026-11-26","academic_year":"Cohort 2030 (Fall 2027 admission)","deadline":"Fall 2027 (Cohort 2030): NursingCAS applications October 2026 through March 15, 2027 (all rounds due March 15, 2027)","notes":"Pre-nursing (Heritage) and transfer pathways list prerequisites differently: the pre-nursing section names CHEM 101/101L or 110/110L and BIOL 340/340L (C or better); MATH 96-level competency is required before CHEM 101. Pre-nursing placement requires at least three of BIOL 110, BIOL 111, ENG 101, PSY 101, SOC 101, PHIL 210, UNIV 101 with C+ or better. B- or better required in any NURS course. The page says prerequisites must be earned 'prior to admission' without saying whether they may be in progress at application."},
